package pad

// Cells returns every index of s.
func Cells(s string) []int {
	var out []int
	for i := 0; i <= len(s); i++ {
		out = append(out, i)
	}
	return out
}

// Last returns the final byte.
func Last(s string) byte {
	return s[len(s)-1]
}

