	"strings"
)

func FormatCell0(id int) string {
	return fmt.Sprintf("cell-%04d", id)
}

func NormalizeCell1(s string) string {
	return strings.ToLower(strings.TrimSpace(s))
}

func FormatRow2(id int) string {
	return fmt.Sprintf("row-%04d", id)
}

